#!/bin/bash#============================================================================# ORCA AI Accelerator Series — GitHub Push Script# Usage: ./push_to_github.sh [github_token]#   If token is provided, uses HTTPS with token auth#   If no token, assumes SSH key is configured#============================================================================set -eREPO_NAME='orca-ai-accelerators'GITHUB_USER='tonythetiger168'REPO_URL_HTTPS='https://github.com/tonythetiger168/orca-ai-accelerators.git'REPO_URL_SSH='git@github.com:tonythetiger168/orca-ai-accelerators.git'GITHUB_TOKEN=${1:-}echo '=============================================================='echo '  ORCA AI Accelerator Series — GitHub Push Script'echo '  Repository: tonythetiger168/orca-ai-accelerators'echo '=============================================================='echo ''# Check if we're in the repo rootif [ ! -f 'README.md' ] || [ ! -d 'v6_0_phoenix' ]; then    echo 'Error: Please run this script from the orca_ai_accelerators/ directory'    exit 1fi# Configure git if not already setif [ -z '$(git config user.name 2>/dev/null)' ]; then    git config user.name 'tonythetiger168'    git config user.email 'tonythetiger168@users.noreply.github.com'fi# Initialize git if neededif [ ! -d '.git' ]; then    echo '[1/6] Initializing git repository...'    git init    git branch -M mainelse    echo '[1/6] Git repository already initialized'fi# Add all files echo '[2/6] Adding files to staging...'git add .echo '[3/6] Creating initial commit...'git commit -m 'ORCA AI Accelerator Series v2.0 — Initial Release  7 generations of AI accelerators: Kestrel → Falcon → Hawk → Phoenix → Phoenix-E → Phoenix+  - 9 RTL modules (SystemVerilog)  - 6 SoC integration modules  - 9 architecture specification documents  - UCIe die-to-die verification testbench  - 2.5D CoWoS package planning  - LLVM/MLIR compiler backend guide  - Apache 2.0 licensed' || echo 'Commit already exists, continuing...'# Set remote originif [ -n '$GITHUB_TOKEN' ]; then    REPO_URL='https://${GITHUB_TOKEN}@github.com/${GITHUB_USER}/${REPO_NAME}.git'    echo '[4/6] Using HTTPS with token authentication...'elif [ -f '$HOME/.ssh/id_rsa' ] || [ -f '$HOME/.ssh/id_ed25519' ]; then    REPO_URL=${REPO_URL_SSH}    echo '[4/6] Using SSH authentication...'else    REPO_URL=${REPO_URL_HTTPS}    echo '[4/6] Using HTTPS (you will be prompted for password/token)...'fi# Check if remote exists and update if neededif git remote get-url origin >/dev/null 2>&1; then    git remote set-url origin ${REPO_URL}    echo '       Updated existing remote origin'else    git remote add origin ${REPO_URL}    echo '       Added remote origin'fi# Push to GitHub echo '[5/6] Pushing to GitHub...'if git push -u origin main 2>&1; then    echo '[6/6] Push successful!'else    echo ''    echo '=============================================================='    echo '  Push failed. Common causes:'    echo '=============================================================='    echo ''    echo '  1. Repository does not exist on GitHub yet:'    echo '     → Go to https://github.com/new and create:'    echo '     → Repository name: orca-ai-accelerators'    echo '     → Visibility: Public'    echo '     → Do NOT initialize with README'    echo ''    echo '  2. Authentication failed:'    echo '     → For HTTPS: Use personal access token (not password)'    echo '     → For SSH: Ensure key is added to ssh-agent'    echo '       eval $(ssh-agent -s)'    echo '       ssh-add ~/.ssh/id_ed25519'    echo ''    echo '  3. Branch name mismatch:'    echo '     → git branch -M main'    echo ''    exit 1fi echo ''echo '=============================================================='echo '  Successfully pushed to GitHub!'echo '=============================================================='echo ''echo '  Repository URL:'echo '    https://github.com/tonythetiger168/orca-ai-accelerators'echo ''echo '  Next steps:'echo '    1. Visit the repository URL to verify'echo '    2. Enable GitHub Actions: Settings → Actions → Allow all actions'echo '    3. Add repository description and topics'echo '    4. Pin to your profile for visibility'echo ''